# Generated by aigate-cli init powershell. No credentials or API requests.
& {
    $root = ConvertFrom-Json @'
__AIGATE_SCHEMA__
'@
    $completer = {
        param($wordToComplete, $commandAst, $cursorPosition)
        $node = $root
        $pending = $null
        $position = 0
        $literal = $false
        # Read only complete tokens before the word under the cursor. String AST
        # values preserve quoted paths and Unicode without evaluating expressions.
        $start = $cursorPosition - $wordToComplete.Length
        foreach ($element in @($commandAst.CommandElements | Select-Object -Skip 1)) {
            if ($element.Extent.StartOffset -ge $start) { break }
            $word = $element.Extent.Text
            if ($element -is [System.Management.Automation.Language.StringConstantExpressionAst]) {
                $word = $element.Value
            }
            if ($null -ne $pending) { $pending = $null; continue }
            if ($word -eq '--' -and -not $literal) { $literal = $true; continue }
            if (-not $literal) {
                $name = ($word -split '=', 2)[0]
                $option = $node.options | Where-Object { $_.name -ceq $name } | Select-Object -First 1
                if ($null -ne $option) {
                    if ($option.takesValue -and -not $word.Contains('=')) { $pending = $option }
                    continue
                }
                $child = $node.subcommands | Where-Object { $_.names -ccontains $word } | Select-Object -First 1
                if ($null -ne $child) { $node = $child.command; $position = 0; continue }
                if ($word.StartsWith('-')) { continue }
            }
            $position++
        }

        $prefix = $wordToComplete.Trim("'", '"')
        $leading = ''
        if ($null -eq $pending -and -not $literal -and $prefix -match '^(--[^=]+)=(.*)$') {
            $name = $Matches[1]
            $leading = $name + '='
            $prefix = $Matches[2].Trim("'", '"')
            $pending = $node.options | Where-Object { $_.name -ceq $name } | Select-Object -First 1
        }
        $candidates = @()
        $path = $false
        if ($null -ne $pending) {
            $candidates = @($pending.values)
            $path = $pending.path
        } elseif (-not $literal -and $prefix.StartsWith('-')) {
            $candidates = @($node.options | ForEach-Object { $_.name })
        } else {
            if (-not $literal) {
                $candidates = @($node.subcommands | ForEach-Object { $_.names })
            }
            if ($position -lt @($node.positionals).Count) {
                $arg = $node.positionals[$position]
                $candidates += @($arg.values)
                $path = $arg.path
            }
        }
        if ($path) {
            foreach ($match in [System.Management.Automation.CompletionCompleters]::CompleteFilename($prefix)) {
                [System.Management.Automation.CompletionResult]::new(
                    $leading + $match.CompletionText, $match.ListItemText, $match.ResultType, $match.ToolTip)
            }
        }
        foreach ($candidate in $candidates | Sort-Object -Unique) {
            if ($null -ne $candidate -and $candidate.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
                [System.Management.Automation.CompletionResult]::new(
                    $leading + $candidate, $candidate, 'ParameterValue', $candidate)
            }
        }
    }.GetNewClosure()
    Register-ArgumentCompleter -Native -CommandName aigate-cli,aigate-cli.exe -ScriptBlock $completer
}
